#!/usr/bin/env python3
"""Oracle vectors for the Kotlin login port (`apple/login/`), generated by running the real Python.

    python app/tools/oracle/login_vectors.py [OUT_DIR]

Writes, under OUT_DIR (default: the test fixtures directory `fixtures/login/`):

* `crypto.json`  -- SRP-6a (pysrp exactly as `findmy.reports.account` configures it), both PBKDF2
  password derivations (`s2k`, `s2k_fo`), the encrypted `spd` decoding, including the leading-zero
  cases of `A` and `B` that only a minimal big-endian encoding gets right.
* `headers.json` -- the Anisette header set, `cpd`, client-info and user-agent composites, the
  two-factor identity token, the JSON bodies and the phone-number extraction from the `/auth` page.
* `flows.json`   -- whole exchanges: `AsyncAppleAccount` itself (plus `auth_probe.py`'s hsc-409 and
  434-resync wrappers, which our real login runs with) driven against a scripted Grand Slam /
  setup.icloud.com server, recording every request Python sends and every reply it got.

Everything is synthetic and deterministic: fixed passwords, salts, ephemeral secrets, UUIDs and
clock. Nothing here talks to a network: the account's HTTP session is replaced before any call.
"""

from __future__ import annotations

import asyncio
import base64
import contextlib
import hashlib
import hmac
import io
import json
import plistlib
import sys
from pathlib import Path

