# (rfc5054_enable + no_username_in_x). Every SRP value below depends on it.
import findmy.reports.account as account_mod  # noqa: F401
import srp._pysrp as srp
from cryptography.hazmat.primitives import padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from findmy.reports.account import AsyncAppleAccount, _extract_phone_numbers
from findmy.reports.anisette import BaseAnisetteProvider, DeviceIdentity
from findmy.reports.state import LoginState
from findmy.reports.twofactor import AsyncSmsSecondFactor, AsyncTrustedDeviceSecondFactor
from findmy.util import crypto, parsers
from findmy.util.http import HttpResponse

EMULATION = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(EMULATION / "tools" / "machoadi"))
import auth_probe  # noqa: E402  -- our driver: the hsc-409 and 434 wrappers the real login runs with

HERE = Path(__file__).resolve().parent
DEFAULT_OUT = HERE.parent.parent / "android/app/src/test/resources/fixtures/login"

N, G = srp.get_ng(srp.NG_2048, None, None)

# The identity tools/machoadi/provider.py logs in as (macOS 13.1, build 22C65, one release).
IDENTITY = DeviceIdentity(model="MacBookPro13,2", os_name="macOS", os_version="13.1", os_build="22C65",
                          cfnetwork="1404.0.5", darwin="22.2.0")
SERIAL = "C02SYNTH0001"
UID = "8F2C6A1E5B7D49C3A0E1F2D3C4B5A697"           # the machine's local user uuid (synthetic)
DEVID = "00006000-0A1B2C3D4E5F6071"                # a Mac-style provisioning UDID (synthetic)
FIXED = {
    "otp": base64.b64encode(bytes(range(28))).decode(),
    "mid": base64.b64encode(bytes(range(100, 160))).decode(),
    "routing": "84215045",
    "time": "2026-10-17T12:34:56Z",
    "tz": "UTC",
    "locale": "en_US",
}


def det(label: str, n: int) -> bytes:
    """n deterministic bytes from a label."""
    out = b""
    counter = 0
    while len(out) < n:
        out += hashlib.sha256(f"{label}/{counter}".encode()).digest()
        counter += 1
    return out[:n]


def b64(b: bytes) -> str:
    return base64.b64encode(b).decode()


def jsonable(v):  # noqa: ANN001, ANN201
    """Plist values as JSON: bytes become {"$data": base64}."""
    if isinstance(v, bytes):
        return {"$data": b64(v)}
    if isinstance(v, dict):
        return {k: jsonable(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        return [jsonable(x) for x in v]
    return v


def lb(n: int) -> bytes:
    return srp.long_to_bytes(n)


# --------------------------------------------------------------------------- crypto vectors

def srp_case(name: str, username: str, password: str, sp: str, salt: bytes, iterations: int,
             a: bytes, b: bytes) -> dict:
    p = crypto.encrypt_password(password, salt, iterations, sp)
    usr = srp.User(username, b"", hash_alg=srp.SHA256, ng_type=srp.NG_2048, bytes_a=a)
    _, a_pub = usr.start_authentication()
    x = srp.gen_x(hashlib.sha256, salt, username, p)
    v = pow(G, x, N)
    ver = srp.Verifier(username, salt, lb(v), a_pub, hash_alg=srp.SHA256, ng_type=srp.NG_2048, bytes_b=b)
    s, b_pub = ver.get_challenge()
    usr.p = p
    m1 = usr.process_challenge(s, b_pub)
    m2 = ver.verify_session(m1)
    assert m2 is not None, name
    usr.verify_session(m2)
    assert usr.authenticated(), name
    return {
        "name": name, "username": username, "password": password, "sp": sp, "salt": b64(salt),
        "iterations": iterations, "a": a.hex(), "b": b.hex(),
        "P": p.hex(), "x": hex(x)[2:], "u": hex(usr.u)[2:], "k": hex(usr.k)[2:],
        "A": a_pub.hex(), "B": b_pub.hex(), "S": hex(usr.S)[2:],
        "K": usr.get_session_key().hex(), "M1": m1.hex(), "M2": m2.hex(),
    }


def leading_zero(label: str, want: str, username: str, password: str, salt: bytes, iterations: int) -> tuple[bytes, bytes]:
    """Find (a, b) whose A (or B) has a leading zero byte in its 256-byte form."""
    p = crypto.encrypt_password(password, salt, iterations, "s2k")
    v = pow(G, srp.gen_x(hashlib.sha256, salt, username, p), N)
    k = srp.bytes_to_long(srp.H(hashlib.sha256, N, G, width=256))
    for i in range(20000):
        cand = det(f"{label}/{i}", 256)
        if want == "A" and len(lb(pow(G, srp.bytes_to_long(cand), N))) < 256:
            return cand, det(f"{label}/b", 256)
        if want == "B" and len(lb((k * v + pow(G, srp.bytes_to_long(cand), N)) % N)) < 256:
            return det(f"{label}/a", 256), cand
    raise SystemExit(f"no leading-zero {want} found")


def spd_encrypt(k: bytes, plaintext: bytes) -> bytes:
    key = hmac.new(k, b"extra data key:", hashlib.sha256).digest()
    iv = hmac.new(k, b"extra data iv:", hashlib.sha256).digest()[:16]
    padder = padding.PKCS7(128).padder()
    data = padder.update(plaintext) + padder.finalize()
    enc = Cipher(algorithms.AES(key), modes.CBC(iv)).encryptor()
    return enc.update(data) + enc.finalize()


def crypto_vectors() -> dict:
    user = "synthetic.user@example.invalid"
    salt = det("salt", 16)
    cases = [
        srp_case("s2k", user, "correct horse battery staple", "s2k", salt, 20082, det("a1", 256), det("b1", 256)),
        srp_case("s2k_fo", user, "correct horse battery staple", "s2k_fo", salt, 1000, det("a2", 256), det("b2", 256)),
        srp_case("non_ascii", "Ünïcødé@example.invalid", "pässwörd-☃-密码", "s2k", det("salt3", 16), 777,
                 det("a3", 256), det("b3", 256)),
    ]
    a, b = leading_zero("lzA", "A", user, "pw", salt, 500)
    cases.append(srp_case("leading_zero_A", user, "pw", "s2k", salt, 500, a, b))
    a, b = leading_zero("lzB", "B", user, "pw", salt, 500)
    cases.append(srp_case("leading_zero_B", user, "pw", "s2k", salt, 500, a, b))

    pbkdf2 = []
    for pw, sp, it in [("", "s2k", 1), ("hunter2", "s2k", 1000), ("hunter2", "s2k_fo", 1000),
                       ("pässwörd-☃-密码", "s2k", 20082), ("pässwörd-☃-密码", "s2k_fo", 20082)]:
        pbkdf2.append({"password": pw, "sp": sp, "iterations": it, "salt": b64(salt),
                       "P": crypto.encrypt_password(pw, salt, it, sp).hex()})

    k = bytes.fromhex(cases[0]["K"])
    payload = {"adsid": "000123-05-synthetic", "GsIdmsToken": "SYNTH-IDMS", "acname": user, "fn": "Synth",
               "ln": "User", "DsPrsId": 1234567890, "t": {"com.apple.gs.idms.pet": {"token": "PET-1", "expiry": 1792243200000, "duration": 300}},
               "flag": True, "blob": b"\x00\x01binary"}
    with_prolog = plistlib.dumps(payload)
    bare = with_prolog[with_prolog.index(b"<plist"):]
    spd = []
    for label, plain in [("with_prolog", with_prolog), ("without_prolog", bare)]:
        ct = spd_encrypt(k, plain)
        decoded = parsers.decode_plist(crypto.decrypt_spd_aes_cbc(k, ct))
        spd.append({"name": label, "K": k.hex(), "spd": b64(ct), "plaintext": b64(plain), "decoded": jsonable(decoded)})
    return {"srp": cases, "pbkdf2": pbkdf2, "spd": spd}


# --------------------------------------------------------------------------- header/body vectors

class FixedProvider(BaseAnisetteProvider):
    """A provider whose every value is fixed: the clock, the zone, the locale, OTP, MID and routing."""

    def __init__(self) -> None:
        super().__init__(serial=SERIAL, identity=IDENTITY)
        self._window = None  # auth_probe resets this after a resync

    otp = property(lambda self: FIXED["otp"])
    machine = property(lambda self: FIXED["mid"])
    router = property(lambda self: FIXED["routing"])
    timestamp = property(lambda self: FIXED["time"])
    timezone = property(lambda self: FIXED["tz"])
    locale = property(lambda self: FIXED["locale"])

    async def close(self) -> None:
        return None

    def to_json(self, dst=None, /):  # noqa: ANN001, ANN201
        raise NotImplementedError

    @classmethod
    def from_json(cls, mapping):  # noqa: ANN001, ANN206
        raise NotImplementedError


BOOT_ARGS_HTML = (
    "<!DOCTYPE html><html><head><title>Verify</title>"
    '<script type="application/json" class="boot_args">'
    '{"direct":{"phoneNumberVerification":{"trustedPhoneNumbers":['
    '{"id":1,"numberWithDialCode":"+1 (•••) •••-••12","pushMode":"sms","lastTwoDigits":"12"},'
    '{"id":2,"numberWithDialCode":"+39 ••• ••• ••34"},'
    '{"numberWithDialCode":null}]}}}'
    "</script></head><body></body></html>"
)


def header_vectors() -> dict:
    prov = FixedProvider()

    async def run() -> dict:
        return {
            "get_headers": await prov.get_headers(UID, DEVID),
            "get_headers_with_client_info": await prov.get_headers(UID, DEVID, with_client_info=True),
            "get_cpd": await prov.get_cpd(UID, DEVID),
        }

    got = asyncio.run(run())
    phones = []
    for label, html in [
        ("boot_args", BOOT_ARGS_HTML),
        ("multi_class", BOOT_ARGS_HTML.replace('class="boot_args"', 'class="x boot_args y"')),
        ("empty_direct", '<html><script class="boot_args">{"other":1}</script></html>'),
    ]:
        phones.append({"name": label, "html": html, "numbers": _extract_phone_numbers(html)})
    try:
        _extract_phone_numbers("<html><body>no script</body></html>")
        missing = "no error"
    except RuntimeError as e:
        missing = f"RuntimeError: {e}"
    adsid, idms = "000123-05-synthetic", "SYNTH-IDMS"
    return {
        "fixed": FIXED, "uid": UID, "devid": DEVID, "serial": SERIAL,
        "identity": IDENTITY.to_json(),
        **got,
        "client_xcode": prov.client,
        "client_akd": prov.client_akd,
        "akd_user_agent": prov.akd_user_agent,
        "icloud_helper_user_agent": IDENTITY.user_agent(account_mod._ICLOUD_HELPER),
        "accountsd_client_info": IDENTITY.client_info(account_mod._ACCOUNTSD_BUNDLE),
        "gsa_user_agent": account_mod._GSA_USER_AGENT,
        "identity_token": {"adsid": adsid, "idms_token": idms,
                           "value": base64.b64encode((adsid + ":" + idms).encode()).decode()},
        "sms_request_body": json.dumps({"phoneNumber": {"id": 2}, "mode": "sms"}),
        "sms_submit_body": json.dumps({"phoneNumber": {"id": 2}, "securityCode": {"code": "123456"}, "mode": "sms"}),
        "phones": phones, "phones_missing_script": missing,
    }


# --------------------------------------------------------------------------- whole flows

class Scripted:
    """The server side: Grand Slam (pysrp's Verifier), the delegate endpoint, and the 2FA pages."""

    def __init__(self, sc: dict) -> None:
        self.sc = sc
        self.ver = None
        self.inits = 0
        self.completes = 0

    def _gsa(self, req: dict) -> dict:
        sc = self.sc
        if req["o"] == "init":
            self.inits += 1
            if self.inits in sc.get("resync_on_init", ()):
                return {"Status": {"ec": -22421, "em": "Anisette Resync Required", "hsc": 434,
                                   "X-Apple-I-MD-DATA": b64(b"SYNTHETIC-SIM")}}
            # The server's verifier is for the account's real password; the wrong-password case types another.
            p = crypto.encrypt_password(sc.get("server_password", sc["password"]), sc["salt"], sc["iterations"], sc["sp"])
            v = pow(G, srp.gen_x(hashlib.sha256, sc["salt"], sc["username"], p), N)
            b = det(f"{sc['name']}/b/{self.inits}", 256)
            self.ver = srp.Verifier(sc["username"], sc["salt"], lb(v), req["A2k"], hash_alg=srp.SHA256,
                                    ng_type=srp.NG_2048, bytes_b=b)
            s, b_pub = self.ver.get_challenge()
            return {"Status": {"ec": 0}, "s": s, "B": b_pub, "c": f"continuation-{self.inits}",
                    "i": sc["iterations"], "sp": sc["sp"]}
        self.completes += 1
        m2 = self.ver.verify_session(req["M1"])
        if m2 is None:
            return {"Status": {"ec": -22406, "em": "Your Apple ID or password was entered incorrectly."}}
        status = dict(sc["complete_status"][self.completes - 1])
        two_fa = bool(status.get("au")) or status.get("hsc") == 409
        spd = {"adsid": sc["adsid"], "GsIdmsToken": sc["idms"], "acname": sc["username"].lower(),
               "fn": "Synth", "ln": "User", "DsPrsId": 1234567890}
        if not two_fa:
            spd["t"] = {
                "com.apple.gs.idms.pet": {"token": f"PET-{self.completes}", "expiry": 1792243200000, "duration": 300},
                "com.apple.gs.idms.hb": {"token": f"HB-{self.completes}", "expiry": 1823779200000, "duration": 31536000},
            }
        else:
            spd["t"] = {"com.apple.gs.appleid.auth": {"token": "AUTH", "duration": 300}}
        return {"Status": status, "M2": m2, "spd": spd_encrypt(self.ver.K, plistlib.dumps(spd))}

    def __call__(self, method: str, url: str, body: bytes) -> tuple[int, dict, bytes]:
        if url.endswith("/grandslam/GsService2"):
            req = plistlib.loads(body)["Request"]
            return 200, {"Content-Type": "text/x-xml-plist"}, plistlib.dumps({"Response": self._gsa(req)})
        if url.endswith("/loginDelegates"):
            reply = {"dsid": "1234567890", "status": 0, "delegates": {"com.apple.mobileme": {
                "status": 0, "service-data": {
                    "tokens": {"mmeAuthToken": "MME-AUTH", "cloudKitToken": "CK-TOKEN", "searchPartyToken": "SP-TOKEN",
                               "mmeFMIPToken": "FMIP"},
                    "com.apple.mobileme": {"url": "https://p00-setup.example.invalid"},
                }}}}
            return 200, {"Content-Type": "text/xml"}, plistlib.dumps(reply)
        if url.endswith("/auth"):
            return 200, {"Content-Type": "text/html"}, BOOT_ARGS_HTML.encode()
        if url.endswith("/auth/verify/trusteddevice"):
            return 200, {}, b""
        if url.endswith("/GsService2/validate"):
            return 200, {"Content-Type": "text/x-xml-plist"}, plistlib.dumps({"Response": {"Status": {"ec": 0}}})
        if url.endswith("/auth/verify/phone"):
            return 200, {"Content-Type": "application/json"}, b'{"phoneNumber":{"id":2},"mode":"sms"}'
        if url.endswith("/auth/verify/phone/securitycode"):
            return 200, {"Content-Type": "application/json"}, b"{}"
        return 404, {}, b""


class FakeHttp:
    """Stands in for `findmy.util.http.HttpSession`; records what the account sends."""

    def __init__(self, server: Scripted) -> None:
        self.server = server
        self.log: list[dict] = []

    async def post(self, url, **kw):  # noqa: ANN001, ANN003, ANN201
        return await self.request("POST", url, **kw)

    async def get(self, url, **kw):  # noqa: ANN001, ANN003, ANN201
        return await self.request("GET", url, **kw)

    async def request(self, method, url, *, headers=None, data=None, json=None, auth=None, **kw):  # noqa: ANN001, ANN003, ANN201, A002
        headers = dict(headers or {})
        if json is not None:
            body, kind, implied = __import__("json").dumps(json).encode(), "json", "application/json"
        elif data is not None:
            body, kind = data, "plist"
            implied = None if any(k.lower() == "content-type" for k in headers) else "application/octet-stream"
        else:
            body, kind, implied = b"", "none", None
        status, rheaders, rbody = self.server(method, url, body)
        self.log.append({
            "method": method, "url": url, "headers": headers,
            "auth": list(auth) if auth else None,
            "body_kind": kind, "body": b64(body), "implied_content_type": implied,
            "response": {"status": status, "headers": rheaders, "body": b64(rbody)},
        })
        return HttpResponse(status, rbody, rheaders)

    async def close(self) -> None:
        return None


class FakeResyncer:
    def __init__(self) -> None:
        self.sims: list[str] = []
        self.on_synced = None
        self.preflight = False

    def age(self) -> int:
        return 0

    async def answer_sim(self, sim: str) -> dict:
        self.sims.append(sim)
        if self.on_synced:
            self.on_synced()
        return {"ok": True, "ec": 0}


def flow(sc: dict) -> dict:
    a_values = [det(f"{sc['name']}/a/{i}", 256) for i in range(8)]
    used: list[bytes] = []

    def fake_random(nbytes: int) -> int:
        assert nbytes == 256
        v = a_values[len(used)]
        used.append(v)
        return srp.bytes_to_long(v)  # pysrp sets the top bit itself; our a values already carry it below

    for i, v in enumerate(a_values):  # match get_random_of_length: the top bit is always set
        a_values[i] = bytes([v[0] | 0x80]) + v[1:]

    original = srp.get_random_of_length
    srp.get_random_of_length = fake_random
    server = Scripted(sc)
    http = FakeHttp(server)
    resyncer = FakeResyncer()
    outcome: dict = {}

    async def run() -> None:
        acc = AsyncAppleAccount(FixedProvider(), uid=UID, devid=DEVID, timeout=30)
        acc._http = http
        with contextlib.redirect_stdout(io.StringIO()):
            auth_probe.trace_requests(acc)                   # the hsc-409 rule
            auth_probe.install_auto_resync(acc, resyncer)    # the 434 answer
            try:
                state = await acc.login(sc["username"], sc["password"])
                outcome["after_login"] = state.name
                if state == LoginState.REQUIRE_2FA:
                    outcome["trusted_device_2fa"] = acc._account_info["trusted_device_2fa"]
                    if sc["second_factor"] == "trusted_device":
                        if sc.get("list_methods"):
                            methods = await acc.get_2fa_methods()
                            outcome["methods"] = [
                                {"kind": "sms", "id": m.phone_number_id, "number": m.phone_number}
                                if isinstance(m, AsyncSmsSecondFactor) else {"kind": "trusted_device"}
                                for m in methods]
                        method = AsyncTrustedDeviceSecondFactor(acc)
                        await method.request()
                        state = await method.submit("123456")
                    else:
                        methods = await acc.get_2fa_methods()
                        outcome["methods"] = [
                            {"kind": "sms", "id": m.phone_number_id, "number": m.phone_number}
                            if isinstance(m, AsyncSmsSecondFactor) else {"kind": "trusted_device"}
                            for m in methods]
                        sms = [m for m in methods if isinstance(m, AsyncSmsSecondFactor)][1]
                        await sms.request()
                        state = await sms.submit("123456")
                outcome["state"] = state.name
                if state == LoginState.LOGGED_IN:
                    outcome["dsid"] = acc.dsid
                    outcome["adsid"] = acc.adsid
                    outcome["account_name"] = acc.account_name
                    outcome["first_name"] = acc.first_name
                    outcome["last_name"] = acc.last_name
                    outcome["tokens"] = dict(acc.service_tokens)
                    outcome["idms_hb"] = acc._login_state_data.get("idms_hb")
                    if sc.get("request_pet"):
                        outcome["pet"] = await acc.request_pet()
                        outcome["state_after_pet"] = acc.login_state.name
            except Exception as e:  # noqa: BLE001 - the error is part of the vector
                outcome["error"] = f"{type(e).__name__}: {e}"
            await acc.close()

    try:
        asyncio.run(run())
    finally:
        srp.get_random_of_length = original
    return {
        "name": sc["name"], "username": sc["username"], "password": sc["password"],
        "a_values": [v.hex() for v in used], "resync_sims": resyncer.sims,
        "anisette": asyncio.run(FixedProvider().get_headers(UID, DEVID)),
        "outcome": outcome, "exchanges": http.log,
    }


def flows() -> list[dict]:
    base = {"username": "Synthetic.User@example.invalid", "password": "correct horse battery staple",
            "salt": det("flow-salt", 16), "iterations": 1000, "adsid": "000123-05-synthetic", "idms": "SYNTH-IDMS"}
    scenarios = [
        {**base, "name": "signin_no_2fa", "sp": "s2k", "complete_status": [{"ec": 0}, {"ec": 0}],
         "second_factor": None, "request_pet": True},
        {**base, "name": "signin_trusted_device", "sp": "s2k_fo",
         "complete_status": [{"ec": 0, "au": "trustedDeviceSecondaryAuth"}, {"ec": 0}],
         "second_factor": "trusted_device", "list_methods": True},
        {**base, "name": "signin_trusted_device_409", "sp": "s2k",
         "complete_status": [{"ec": 0, "hsc": 409}, {"ec": 0}], "second_factor": "trusted_device"},
        {**base, "name": "signin_sms", "sp": "s2k", "complete_status": [{"ec": 0, "au": "secondaryAuth"}, {"ec": 0}],
         "second_factor": "sms"},
        {**base, "name": "resync_434_on_init", "sp": "s2k", "complete_status": [{"ec": 0}],
         "second_factor": None, "resync_on_init": (1,)},
        {**base, "name": "wrong_password", "sp": "s2k", "complete_status": [{"ec": 0}], "second_factor": None,
         "server_password": "the real password"},
    ]
    return [flow(sc) for sc in scenarios]


def main() -> int:
    out = Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_OUT
    out.mkdir(parents=True, exist_ok=True)
    for name, value in [("crypto.json", crypto_vectors()), ("headers.json", header_vectors()), ("flows.json", flows())]:
        (out / name).write_text(json.dumps(value, indent=1, ensure_ascii=False, sort_keys=True) + "\n")
        print("wrote", out / name)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
